import { marked } from 'marked';

export type Book = {
	slug: string;
	title: string;
	author: string;
	year: number;
	rating: number;
	tags: string[];
};

const files = import.meta.glob('/content/books/*.md', {
	query: '?raw',
	import: 'default',
	eager: true
}) as Record<string, string>;

function parse(path: string, raw: string): Book & { body: string } {
	const m = raw.replace(/\r\n/g, '\n').match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/);
	const fm: Record<string, string> = {};
	for (const line of (m?.[1] ?? '').split('\n')) {
		const i = line.indexOf(':');
		if (i > 0) fm[line.slice(0, i).trim()] = line.slice(i + 1).trim();
	}
	const unquote = (s: string) => s.replace(/^(['"])(.*)\1$/, '$2');
	const tags = (fm.tags ?? '')
		.replace(/^\[|\]$/g, '')
		.split(',')
		.map((t) => unquote(t.trim()))
		.filter(Boolean);
	return {
		slug: path.split('/').pop()!.replace(/\.md$/, ''),
		title: unquote(fm.title ?? ''),
		author: unquote(fm.author ?? ''),
		year: Number(fm.year),
		rating: Number(fm.rating),
		tags,
		body: m?.[2] ?? ''
	};
}

const all = Object.entries(files).map(([p, r]) => parse(p, r));

const byTitle = (a: Book, b: Book) => (a.title < b.title ? -1 : a.title > b.title ? 1 : 0);

export function listBooks(): Book[] {
	return all.map(({ body: _b, ...b }) => b).sort(byTitle);
}

export function topRated(n: number): Book[] {
	return listBooks()
		.sort((a, b) => b.rating - a.rating || byTitle(a, b))
		.slice(0, n);
}

export function getBook(slug: string) {
	const b = all.find((x) => x.slug === slug);
	if (!b) return undefined;
	const { body, ...book } = b;
	return { book, html: marked.parse(body, { async: false }) as string };
}
EOF
