import { browser } from '$app/environment';

const KEY = 'bookshelf:favorites';

function load(): string[] {
	if (!browser) return [];
	try {
		const v = JSON.parse(localStorage.getItem(KEY) ?? '[]');
		return Array.isArray(v) ? v : [];
	} catch {
		return [];
	}
}

let slugs = $state<string[]>(load());

export const favorites = {
	has: (slug: string) => slugs.includes(slug),
	toggle(slug: string) {
		slugs = slugs.includes(slug) ? slugs.filter((s) => s !== slug) : [...slugs, slug];
		localStorage.setItem(KEY, JSON.stringify(slugs));
	}
};
EOF
cat > src/lib/validate.ts <<'EOF'
export type Fields = { name: string; email: string; message: string };
export type Errors = Partial<Record<keyof Fields, string>>;

export function validate(v: Fields): Errors {
	const e: Errors = {};
	const name = v.name.trim();
	const email = v.email.trim();
	if (!name) e.name = 'Name is required.';
	if (!email) e.email = 'Email is required.';
	else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) e.email = 'Enter a valid email address.';
	if (v.message.trim().length < 20) e.message = 'Message must be at least 20 characters.';
	return e;
}
