// Runs the built adapter-node handler, taking the site's protocol from ORIGIN
// (adapter-node 6 no longer reads it, and assumes https otherwise).
import { createServer } from 'node:http';

const protocol = new URL(process.env.ORIGIN || 'http://localhost').protocol.slice(0, -1);
process.env.PROTOCOL_HEADER = 'x-forwarded-proto';

const { handler } = await import('./build/handler.js');

const port = Number(process.env.PORT || 3000);
const host = process.env.HOST || '127.0.0.1';

createServer((req, res) => {
	req.headers['x-forwarded-proto'] = protocol;
	handler(req, res, () => {
		res.statusCode = 404;
		res.end('Not found');
	});
}).listen(port, host, () => console.log(`Listening on http://${host}:${port}`));
EOF
